@TestOn('vm')
library;

import 'dart:io';

import 'package:test/test.dart';

import 'support/network_guard.dart';

/// Every ```dart block of the README compiles against the current API: each
/// block becomes a function in one generated file, which must analyze with no
/// issue at all. A block with its own `main` is a file of its own.
void main() {
  installNetworkGuard();

  test('every Dart snippet in the README analyzes cleanly', () async {
    final readme = File('README.md').readAsStringSync();
    final blocks = RegExp(r'```dart\n(.*?)```', dotAll: true)
        .allMatches(readme)
        .map((m) => m[1]!)
        .toList();
    expect(blocks.length, greaterThan(8));
    final dir = Directory('.dart_tool/readme_snippets')
      ..createSync(recursive: true);
    final files = <String>[];
    final wrapped = StringBuffer()
      ..writeln('// Generated by test/readme_test.dart from README.md.')
      ..writeln('// ignore_for_file: unused_local_variable')
      ..writeln("import 'package:zerobounce_sdk/zerobounce_sdk.dart';")
      ..writeln();
    for (var i = 0; i < blocks.length; i++) {
      final block = blocks[i];
      if (block.contains('main()')) {
        final file = File('${dir.path}/snippet_$i.dart')
          ..writeAsStringSync(block);
        files.add(file.path);
        continue;
      }
      final declaresClient = block.contains('final zb = ');
      wrapped
        ..writeln('Future<void> snippet$i() async {')
        ..writeln(declaresClient ? '' : "  final zb = ZeroBounceSDK('key');")
        ..writeln(block)
        ..writeln('}')
        ..writeln();
    }
    final combined = File('${dir.path}/snippets.dart')
      ..writeAsStringSync(wrapped.toString());
    files.add(combined.path);
    final result = await Process.run(
        Platform.resolvedExecutable, ['analyze', '--fatal-infos', ...files]);
    expect(result.exitCode, 0, reason: '${result.stdout}\n${result.stderr}');
  }, timeout: const Timeout(Duration(minutes: 3)));
}
